Based on the images provided, here is the complete C++ code for the **Employee Salary System**.

The code uses a class with static variables to track total salaries for different roles (CEO, Team Manager, Programmer) and uses a destructor to print the results when the object goes out of scope.

```cpp
#include <iostream>
using namespace std;

class employee {
private:
    string CEO;
    string team_manager;
    string programmer;

    int CEO_salary;
    int team_manager_salary;
    int programmer_salary;

    static int CEO_total_salary;
    static int team_manager_total_salary;
    static int programmer_total_salary;

public:
    // Constructor
    employee(string c, string Tm, string p) {
        CEO = c;
        team_manager = Tm;
        programmer = p;

        CEO_salary = 10000;
        team_manager_salary = 6000;
        programmer_salary = 5000;

        // Calculating total salaries based on counts (1 CEO, 3 Managers, 7 Programmers)
        CEO_total_salary = 1 * CEO_salary;
        team_manager_total_salary = 3 * team_manager_salary;
        programmer_total_salary = 7 * programmer_salary;
    }

    // Destructor
    ~employee() {
        cout << "CEO Total salary: " << CEO_total_salary << endl;
        cout << "Team manager total salary: " << team_manager_total_salary << endl;
        cout << "Programmer total salary: " << programmer_total_salary << endl;

        if (CEO_total_salary > team_manager_total_salary && team_manager_total_salary > programmer_total_salary) {
            cout << "CEO salary are highest" << endl;
        }
        else if (team_manager_total_salary > CEO_total_salary && team_manager_total_salary > programmer_total_salary) {
            cout << "Team manger total salary are highest" << endl;
        }
        else {
            cout << "Programmer total salary are highest" << endl;
        }
    }
};

// Initializing static variables
int employee::CEO_total_salary = 0;
int employee::team_manager_total_salary = 0;
int employee::programmer_total_salary = 0;

int main() {
    // Creating object. When main ends, the destructor ~employee() is called automatically.
    employee e1("CEO", "Team manager", "Programmer");

    return 0;
}
```

### Explanation of the Logic:
1.  **Static Variables:** `CEO_total_salary`, `team_manager_total_salary`, and `programmer_total_salary` are static. This means they belong to the class itself, not just one object.
2.  **Constructor:** Inside the constructor, the individual salaries are set (10000, 6000, 5000). Then, the total salaries are calculated assuming there is 1 CEO, 3 Team Managers, and 7 Programmers.
    *   CEO Total: $1 \times 10,000 = 10,000$
    *   Manager Total: $3 \times 6,000 = 18,000$
    *   Programmer Total: $7 \times 5,000 = 35,000$
3.  **Destructor (`~employee`):** This runs automatically when the program finishes (specifically when the object `e1` is destroyed). It prints the totals and compares them to find the highest one. Since 35,000 is the largest, it prints "Programmer total salary are highest".

Based on the images provided, here is the complete C++ code for the **Bag Management System**.

The code defines a `Bag` class with static variables to count total bags created. It includes friend functions to find the most sold size (using hardcoded sales data in the example) and the most expensive bag from an array.

```cpp
#include <iostream>
#include <string>
using namespace std;

class Bag {
private:
    string name;
    int price;
    string sizes;

    static int totalBag;

public:
    // Constructor with default arguments
    Bag(string n = "", int p = 0, string s = "") {
        name = n;
        price = p;
        sizes = s;
        totalBag++;
    }

    // Friend functions declarations
    friend void findMostSold(Bag b[], int n);
    friend void findExpensive(Bag b[], int n);

    // Static function to show total bags
    static void showTotalBag() {
        cout << "Total Bags = " << totalBag << endl;
    }

    // Destructor
    ~Bag() {
    }
};

// Initialize static variable
int Bag::totalBag = 0;

// Function to find most sold size
// Note: The code uses hardcoded values for sales counts (m, l, xl, xxl)
// rather than calculating from the array, based on the image.
void findMostSold(Bag b[], int n) {
    int m = 35;
    int l = 20;
    int xl = 30;
    int xxl = 25;

    int max_sold = m;
    string most_sold_size = "M";

    if (l > max_sold) {
        max_sold = l;
        most_sold_size = "L";
    }

    if (xl > max_sold) {
        max_sold = xl;
        most_sold_size = "XL";
    }

    if (xxl > max_sold) {
        max_sold = xxl;
        most_sold_size = "XXL";
    }

    cout << "Most Sold Bag Size: " << most_sold_size << endl;
    cout << "Number Sold: " << max_sold << endl;
}

// Function to find the most expensive bag
void findExpensive(Bag b[], int n) {
    int max_price = b[0].price;
    int index = 0;

    for (int i = 1; i < n; i++) {
        if (b[i].price > max_price) {
            max_price = b[i].price;
            index = i;
        }
    }

    cout << "\nMost Expensive Bag:" << endl;
    cout << "Name  : " << b[index].name << endl;
    cout << "Size  : " << b[index].sizes << endl;
    cout << "Price : " << b[index].price << endl;
}

int main() {
    // Array of 10 bags. 
    // Note: This calls the constructor 10 times immediately.
    Bag b[10]; 

    for (int i = 0; i < 10; i++) {
        string name, sizes;
        int price;

        cout << "\nEnter details of Bag " << i + 1 << endl;

        cout << "Enter name: ";
        cin >> name;

        cout << "Enter size: ";
        cin >> sizes;

        cout << "Enter price: ";
        cin >> price;

        // Creates a temporary object and assigns it to b[i]
        b[i] = Bag(name, price, sizes);
    }

    Bag::showTotalBag();

    findMostSold(b, 10);

    findExpensive(b, 10);

    return 0;
}
```

### Key Observations from the Code:
1.  **Static Variable `totalBag`**: Every time a `Bag` object is created (including the initial array `Bag b[10]` and the temporary objects inside the loop `Bag(name, price, sizes)`), `totalBag` increments.
2.  **Hardcoded Sales Data**: In `findMostSold`, the variables `m=35`, `l=20`, etc., are hardcoded. This means the function doesn't actually calculate sales from user input in this specific version; it just compares these fixed numbers to determine that "M" (35) is the most sold.
3.  **Friend Functions**: `findMostSold` and `findExpensive` are declared as `friend` so they can access private members like `name`, `price`, and `sizes` directly (e.g., `b[i].price`).

