class Snake {
    Point P, Q, R;
public:
    void move(Point p) {
        P = p;
    }

    void move(Point p, Point q) {
        P = p;
        Q = q;
    }

    void play() {
        P = Point(rand() % 2, rand() % 2);

        while (life > 0) {
            Q = Point(rand() % 2, rand() % 2);

            cout << "\nP = ";
            P.show();
            cout << "Q = ";
            Q.show();

            int a = (P == Q); // Calls overloaded == operator

            if (a == 1) {
                life--;
                cout << "Life = " << life << endl;
            }
            else if (a == 2) {
                score++;
                cout << "Up-Up" << endl;
                R = P + Q;
                cout << "R = ";
                R.show();
                move(Q);
            }
            else if (a == 3) {
                score++;
                cout << "Up-Down" << endl;
                move(P, Q);
            }
            else if (a == 4) {
                score++;
                cout << "Down-Down" << endl;
                move(Q);
            }
            else if (a == 5) {
                score++;
                cout << "Down-Up" << endl;
                move(P, Q);
            }

            cout << "Score = " << score << endl;
        }
    }
};

